import {
  ReservoirPageQuery,
  ReservoirPageQuery$data,
  ReservoirPageQuery$variables,
  ArtifactType,
  ArtifactFilter,
  ArtifactOrderBy,
  ArtifactOrderField,
} from '../__generated__/ReservoirPageQuery.graphql';
import AutoUpdateFetchKeyButton from '../components/AutoUpdateFetchKeyButton';
import BAIRadioGroup from '../components/BAIRadioGroup';
import ScanArtifactModelsFromHuggingFaceModal from '../components/ScanArtifactModelsFromHuggingFaceModal';
import { convertToOrderBy } from '../helper';
import { buildPath } from '../helper/pathBuilder';
import { useWebUINavigate } from '../hooks';
import { useBAIPaginationOptionStateOnSearchParam } from '../hooks/reactPaginationQueryOptions';
import { useSetBAINotification } from '../hooks/useBAINotification';
import { useBAISettingUserState } from '../hooks/useBAISetting';
import { theme } from '../theme-shim';
import { Button } from '@astryxdesign/core/Button';
import { Card } from '@astryxdesign/core/Card';
import { Grid } from '@astryxdesign/core/Grid';
import { IconButton } from '@astryxdesign/core/IconButton';
import { HStack } from '@astryxdesign/core/Stack';
import { Stat } from '@astryxdesign/lab';
import {
  // TODO(needs-backend): BAIHuggingFaceRegistrySettingModal - uncomment when storage-proxy applies DB config via Redis
  BAIImportArtifactModal,
  BAIActivateArtifactsModal,
  BAIActivateArtifactsModalArtifactsFragmentKey,
  BAIArtifactTable,
  BAICard,
  availableArtifactSorterValues,
  type ArtifactSorterKey,
  BAIDeactivateArtifactsModal,
  BAIDeactivateArtifactsModalArtifactsFragmentKey,
  BAIFlex,
  BAIGraphQLPropertyFilter,
  BAIHuggingFaceIcon,
  BAIImportArtifactModalArtifactFragmentKey,
  BAIImportArtifactModalArtifactRevisionFragmentKey,
  BAISelectionLabel,
  INITIAL_FETCH_KEY,
  filterOutEmpty,
  toLocalId,
  useToggle,
  useUpdatableState,
} from 'backend.ai-ui';
import * as _ from 'lodash-es';
import { BanIcon, Brain, UndoIcon } from 'lucide-react';
import {
  parseAsJson,
  parseAsString,
  parseAsStringLiteral,
  useQueryStates,
} from 'nuqs';
import React, { useMemo, useDeferredValue, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { graphql, useLazyLoadQuery } from 'react-relay';

const getStatusFilter = (status: string) => {
  return { availability: [status] };
};

const DEFAULT_ARTIFACT_ORDER: ReadonlyArray<ArtifactOrderBy> = [
  { field: 'UPDATED_AT', direction: 'DESC' },
];
const artifactOrderFieldMap: Record<ArtifactSorterKey, ArtifactOrderField> = {
  name: 'NAME',
  type: 'TYPE',
  size: 'SIZE',
  scannedAt: 'SCANNED_AT',
  updatedAt: 'UPDATED_AT',
};

type ArtifactNode = NonNullable<
  NonNullable<
    NonNullable<ReservoirPageQuery$data['artifacts']>['edges']
  >[number]
>['node'];

const ReservoirPage: React.FC = () => {
  'use memo';
  const { t } = useTranslation();
  const { token } = theme.useToken();
  const navigate = useWebUINavigate();
  const { upsertNotification } = useSetBAINotification();

  const [selectedArtifactIdList, setSelectedArtifactIdList] = useState<
    {
      id: string;
      data: ArtifactNode;
    }[]
  >([]);
  const [selectedArtifacts, setSelectedArtifacts] =
    useState<BAIDeactivateArtifactsModalArtifactsFragmentKey>([]);
  const [selectedRestoreArtifacts, setSelectedRestoreArtifacts] =
    useState<BAIActivateArtifactsModalArtifactsFragmentKey>([]);
  const [selectedArtifact, setSelectedArtifact] =
    useState<BAIImportArtifactModalArtifactFragmentKey | null>(null);
  const [selectedRevision, setSelectedRevision] =
    useState<BAIImportArtifactModalArtifactRevisionFragmentKey>([]);
  const [openHuggingFaceModal, { toggle: toggleOpenHuggingFaceModal }] =
    useToggle();
  const deferredOpenHuggingFaceModal = useDeferredValue(openHuggingFaceModal);
  // TODO(needs-backend): Uncomment when storage-proxy applies DB config via Redis
  // const [
  //   openHuggingFaceSettingModal,
  //   { toggle: toggleHuggingFaceSettingModal },
  // ] = useToggle();
  const [columnOverrides, setColumnOverrides] = useBAISettingUserState(
    'table_column_overrides.ReservoirPage',
  );

  const {
    baiPaginationOption,
    tablePaginationOption,
    setTablePaginationOption,
  } = useBAIPaginationOptionStateOnSearchParam({
    current: 1,
    pageSize: 10,
  });

  const [queryParams, setQuery] = useQueryStates(
    {
      filter: parseAsJson<ArtifactFilter>(
        (value) => value as ArtifactFilter,
      ).withDefault({}),
      mode: parseAsString.withDefault('ALIVE'),
      order: parseAsStringLiteral(availableArtifactSorterValues),
    },
    { history: 'replace' },
  );
  const jsonStringFilter = JSON.stringify(queryParams.filter);

  const queryVariables: ReservoirPageQuery$variables = useMemo(
    () => ({
      offset: baiPaginationOption.offset,
      limit: baiPaginationOption.limit,
      order:
        convertToOrderBy<ArtifactOrderBy>(
          queryParams.order,
          artifactOrderFieldMap,
        ) ?? DEFAULT_ARTIFACT_ORDER,
      filter: _.merge(
        {},
        JSON.parse(jsonStringFilter || '{}'),
        getStatusFilter(queryParams.mode),
      ),
    }),
    [
      baiPaginationOption.offset,
      baiPaginationOption.limit,
      jsonStringFilter,
      queryParams.mode,
      queryParams.order,
    ],
  );
  const deferredQueryVariables = useDeferredValue(queryVariables);

  const [fetchKey, updateFetchKey] = useUpdatableState(INITIAL_FETCH_KEY);
  const deferredFetchKey = useDeferredValue(fetchKey);

  // const [rescanArtifacts, isInflightRescanArtifacts] =
  //   useMutation<ReservoirPageRescanArtifactsMutation>(graphql`
  //     mutation ReservoirPageRescanArtifactsMutation(
  //       $input: ScanArtifactsInput!
  //     ) {
  //       scanArtifacts(input: $input) {
  //         artifacts {
  //           id
  //         }
  //       }
  //     }
  //   `);

  // NOTE: huggingfaceRegistries is queried but unused until storage-proxy supports DB config via Redis
  const { defaultArtifactRegistry, total, artifacts } =
    useLazyLoadQuery<ReservoirPageQuery>(
      graphql`
        query ReservoirPageQuery(
          $order: [ArtifactOrderBy!]
          $limit: Int
          $offset: Int
          $filter: ArtifactFilter
        ) {
          defaultArtifactRegistry(artifactType: MODEL) {
            name
            type
          }
          huggingfaceRegistries @since(version: "25.14.0") {
            edges {
              node {
                id
                ...BAIHuggingFaceRegistrySettingModalFragment
              }
            }
          }
          total: artifacts(filter: { availability: [ALIVE, DELETED] }) {
            count
          }
          artifacts(
            orderBy: $order
            limit: $limit
            offset: $offset
            filter: $filter
          ) {
            count
            edges {
              node {
                id @since(version: "25.17.0")
                ...BAIArtifactTableArtifactFragment
                ...BAIImportArtifactModalArtifactFragment
                ...BAIDeactivateArtifactsModalArtifactsFragment
                ...BAIActivateArtifactsModalArtifactsFragment
                revisions(
                  limit: 1
                  orderBy: [
                    { field: VERSION, direction: DESC }
                    { field: UPDATED_AT, direction: DESC }
                  ]
                ) {
                  edges {
                    node {
                      id
                      ...BAIImportArtifactModalArtifactRevisionFragment
                    }
                  }
                }
              }
            }
          }
        }
      `,
      deferredQueryVariables,
      {
        fetchKey:
          deferredFetchKey === INITIAL_FETCH_KEY ? undefined : deferredFetchKey,
        fetchPolicy:
          deferredFetchKey === INITIAL_FETCH_KEY
            ? 'store-and-network'
            : 'network-only',
      },
    );

  const isAvailableUsingHuggingFace =
    defaultArtifactRegistry?.type === 'HUGGINGFACE';
  const mode = queryParams.mode;

  // TODO: implement when reservoir supports other types
  // const typeFilterGenerator = (type: 'IMAGE' | 'PACKAGE' | 'MODEL') => {
  //   return { type: { eq: type } };
  // };
  // const handleStatisticCardClick = (type: 'IMAGE' | 'PACKAGE' | 'MODEL') => {
  //   setQuery({ filter: typeFilterGenerator(type) });
  // };

  return (
    <BAIFlex direction="column" align="stretch" gap={'md'}>
      {/* antd `Row gutter={[16,16]}` + a single `Col xs={12} sm={8} lg={6}
          xl={4}` -> Astryx `Grid` on the RESPONSIVE-POLICY R1 recipe: the
          widest antd step is `xl={4}` (6-up from 1200px), so minWidth 200 /
          max 6, gutter 16 -> gap 4. W2A-17: grid children take `width: 100%`
          and `minWidth: 0` so a filled track cannot push past its column. */}
      <Grid columns={{ minWidth: 200, max: 6 }} gap={4} width="100%">
        {/* antd `Statistic` -> lab `Stat` (MAPPING §2 LAB; the canary is
            already in the graph for Drawer/Stepper/Tour).
            PILOT-DECISION: `Stat` has no `prefix` slot and no per-value color,
            so the `Brain` glyph moves INTO the ReactNode `value` beside the
            number, and the primary tint on both the number and the card border
            is DROPPED (P19 theme-defaults-first — `Stat` already gives the
            value display emphasis, and a hand-painted `1px solid colorPrimary`
            was antd-era chrome).
            `hoverable` + `cursor: 'pointer'` also go: the click handler that
            justified them (`handleStatisticCardClick`) is commented out, so
            the affordance was promising an interaction the card does not
            have. */}
        <Card style={{ minWidth: 0 }}>
          <Stat
            label="MODEL"
            value={
              <HStack gap={1} align="center">
                <Brain size={16} />
                {total?.count}
              </HStack>
            }
          />
        </Card>
      </Grid>
      <BAICard
        activeTabKey={'artifacts'}
        tabList={[
          {
            key: 'artifacts',
            tab: t('reservoirPage.ReservoirArtifacts'),
          },
        ]}
        styles={{
          body: {
            padding: `${token.paddingSM}px ${token.paddingLG}px ${token.paddingLG}px ${token.paddingLG}px`,
          },
        }}
      >
        <BAIFlex direction="column" align="stretch" gap={'sm'}>
          <BAIFlex justify="between" wrap="wrap" gap={'sm'}>
            <BAIFlex
              gap={'sm'}
              align="start"
              style={{
                flexShrink: 1,
              }}
              wrap="wrap"
            >
              <BAIRadioGroup
                optionType="button"
                options={[
                  {
                    label: t('reservoirPage.Active'),
                    value: 'ALIVE',
                  },
                  {
                    label: t('reservoirPage.Inactive'),
                    value: 'DELETED',
                  },
                ]}
                value={queryParams.mode}
                onChange={(e) => {
                  setQuery({ mode: e.target.value });
                  setTablePaginationOption({ current: 1 });
                  setSelectedArtifactIdList([]);
                  setSelectedArtifacts([]);
                  setSelectedRestoreArtifacts([]);
                }}
              />
              <BAIGraphQLPropertyFilter
                combinationMode="AND"
                onChange={(value) => {
                  setQuery({ filter: value ?? {} });
                }}
                value={queryParams.filter}
                filterProperties={[
                  {
                    fixedOperator: 'contains',
                    key: 'name',
                    propertyLabel: t('reservoirPage.Name'),
                    type: 'string',
                  },
                  {
                    fixedOperator: 'contains',
                    key: 'source',
                    propertyLabel: t('reservoirPage.Source'),
                    type: 'string',
                  },
                  {
                    fixedOperator: 'contains',
                    key: 'registry',
                    propertyLabel: t('reservoirPage.Registry'),
                    type: 'string',
                  },
                  {
                    fixedOperator: 'equals',
                    key: 'type',
                    propertyLabel: t('reservoirPage.Type'),
                    type: 'enum',
                    valueMode: 'scalar',
                    operators: ['equals', 'in'],
                    strictSelection: true,
                    options: _.map(
                      [
                        'MODEL',
                        // TODO: Temporarily disabled until reservoir supports other types.
                        // 'PACKAGE', 'IMAGE'
                      ] satisfies ArtifactType[],
                      (v) => ({
                        label: v,
                        value: v,
                      }),
                    ),
                  },
                ]}
              />
            </BAIFlex>
            <BAIFlex gap={'xs'} align="center">
              {selectedArtifactIdList.length > 0 && (
                <BAIFlex gap="xs">
                  <BAISelectionLabel
                    count={selectedArtifactIdList.length}
                    onClearSelection={() => setSelectedArtifactIdList([])}
                  />
                  {/* antd `Tooltip` wrapping an icon-only `Button` ->
                      `IconButton`, which requires `label` and renders the
                      tooltip itself, so the wrapper disappears and the button
                      finally has an accessible name. */}
                  <IconButton
                    variant="secondary"
                    label={
                      mode === 'ALIVE'
                        ? t('reservoirPage.Deactivate')
                        : t('reservoirPage.Activate')
                    }
                    tooltip={
                      mode === 'ALIVE'
                        ? t('reservoirPage.Deactivate')
                        : t('reservoirPage.Activate')
                    }
                    icon={
                      mode === 'ALIVE' ? (
                        <BanIcon style={{ color: token.colorError }} />
                      ) : (
                        <UndoIcon style={{ color: token.colorInfo }} />
                      )
                    }
                    onClick={() => {
                      if (mode === 'ALIVE') {
                        setSelectedArtifacts(
                          selectedArtifactIdList.flatMap((arr) => arr.data),
                        );
                      } else {
                        setSelectedRestoreArtifacts(
                          selectedArtifactIdList.flatMap((arr) => arr.data),
                        );
                      }
                    }}
                  />
                </BAIFlex>
              )}
              <AutoUpdateFetchKeyButton
                settingId="reservoir"
                value={fetchKey}
                loading={deferredFetchKey !== fetchKey}
                onChange={() => {
                  updateFetchKey();
                  // rescanArtifacts({
                  //   variables: {
                  //     input: {
                  //       registryId: 'fe878f09-06cc-4b91-9242-4c71015cce05',
                  //       limit: 100,
                  //     },
                  //   },
                  // });
                }}
              />
              {isAvailableUsingHuggingFace && (
                <>
                  {/* TODO(needs-backend): HuggingFace registry token setting button is hidden
                     until storage-proxy applies DB config via Redis stateful state sharing. */}
                  {/* <IconButton
                        variant="secondary"
                        label={t('button.Settings')}
                        tooltip={t('button.Settings')}
                        icon={<Settings size={16} />}
                        onClick={() => toggleHuggingFaceSettingModal()}
                      /> */}
                  <Button
                    variant="primary"
                    icon={
                      <BAIHuggingFaceIcon
                        style={{
                          fontSize: '1.5em',
                        }}
                      />
                    }
                    label={t('reservoirPage.FromHuggingFace')}
                    onClick={() => toggleOpenHuggingFaceModal()}
                  />
                </>
              )}
            </BAIFlex>
          </BAIFlex>
          <BAIArtifactTable
            order={queryParams.order}
            onChangeOrder={(order) => {
              setQuery({ order: order ?? null });
              setTablePaginationOption({ current: 1 });
            }}
            artifactFragment={filterOutEmpty(
              artifacts?.edges.map((e) => e?.node) ?? [],
            )}
            onClickPull={(artifactId: string, revisionId: string) => {
              artifacts?.edges.forEach((artifact) => {
                if (artifact.node.id === artifactId) {
                  setSelectedArtifact(artifact.node);
                  artifact.node.revisions?.edges.forEach((revision) => {
                    if (revision.node.id === revisionId) {
                      setSelectedRevision([revision.node]);
                      return;
                    }
                  });
                  return;
                }
              });
            }}
            onClickDelete={(artifactId: string) => {
              artifacts?.edges.forEach((edge) => {
                if (edge.node.id === artifactId) {
                  setSelectedArtifacts([edge.node]);
                  return;
                }
              });
            }}
            onClickRestore={(artifactId: string) => {
              artifacts?.edges.forEach((edge) => {
                if (edge.node.id === artifactId) {
                  setSelectedRestoreArtifacts([edge.node]);
                  return;
                }
              });
            }}
            rowSelection={{
              type: 'checkbox',
              onChange: (keys) => {
                const artifactIdList =
                  artifacts?.edges.map((e) => e.node.id) ?? [];
                setSelectedArtifactIdList((prev) => {
                  const _filtered = prev.filter(
                    (v) => !artifactIdList.includes(v.id),
                  );
                  const _selected =
                    artifacts?.edges
                      .filter((e) => keys.includes(e.node.id))
                      .map((arr) => ({
                        id: arr.node.id,
                        data: arr.node,
                      })) ?? [];
                  return _filtered.concat(_selected);
                });
              },
              selectedRowKeys: selectedArtifactIdList.map((v) => v.id),
            }}
            loading={deferredQueryVariables !== queryVariables}
            pagination={{
              pageSize: tablePaginationOption.pageSize,
              current: tablePaginationOption.current,
              total: artifacts?.count,
              onChange: (current, pageSize) => {
                if (_.isNumber(current) && _.isNumber(pageSize)) {
                  setTablePaginationOption({ current, pageSize });
                }
              },
            }}
            tableSettings={{
              columnOverrides: columnOverrides,
              onColumnOverridesChange: setColumnOverrides,
            }}
          />
        </BAIFlex>
        {/* TODO: implement audit log for reservoir page */}
        {/* {curTabKey === 'audit' ? (
          <Suspense fallback={<Skeleton active />}>
            <ReservoirAuditLogList
              auditLogs={filteredAuditLogs}
              loading={false}
              filterValue={queryParams.auditFilter}
              onFilterChange={(value) => {
                setQuery({ auditFilter: value });
              }}
              pagination={{
                pageSize: tablePaginationOption.pageSize,
                current: tablePaginationOption.current,
                total: filteredAuditLogs.length,
                showTotal: (total) => (
                  <BAIText type="secondary">
                    {t('general.TotalItems', { total: total })}
                  </BAIText>
                ),
                onChange: (current, pageSize) => {
                  if (_.isNumber(current) && _.isNumber(pageSize)) {
                    setTablePaginationOption({ current, pageSize });
                  }
                },
              }}
              order={queryParams.auditOrder}
              onChangeOrder={(order) => {
                setQuery({ auditOrder: order });
              }}
            />
          </Suspense>
        ) : null} */}
      </BAICard>
      <BAIImportArtifactModal
        selectedArtifactFrgmt={selectedArtifact}
        selectedArtifactRevisionFrgmt={selectedRevision}
        open={!!selectedArtifact && !_.isEmpty(selectedRevision)}
        onOk={(_e, tasks) => {
          setSelectedArtifact(null);
          setSelectedRevision([]);
          tasks.forEach((task) => {
            upsertNotification({
              message: t('reservoirPage.PullingArtifact', {
                name: task.artifact.name,
                version: task.version,
              }),
              type: 'info',
              open: true,
              duration: 0,
              backgroundTask: {
                status: 'pending',
                taskId: task.taskId,
                promise: null,
                percent: 0,
                onChange: {
                  resolved: (_data, _notification) => {
                    return {
                      type: 'success',
                      message: t('reservoirPage.SuccessFullyPulledArtifact', {
                        name: task.artifact.name,
                        version: task.version,
                      }),
                      toText: t('reservoirPage.GoToArtifact'),
                      to: buildPath('admin', `reservoir/${task.artifact.id}`),
                    };
                  },
                  rejected: (_data, _notification) => {
                    return t('reservoirPage.FailedToPullArtifact', {
                      name: task.artifact.name,
                      version: task.version,
                    });
                  },
                },
              },
            });
          });
        }}
        onCancel={() => {
          setSelectedArtifact(null);
          setSelectedRevision([]);
        }}
      />
      <ScanArtifactModelsFromHuggingFaceModal
        open={deferredOpenHuggingFaceModal}
        onRequestClose={(_e, artifactId) => {
          toggleOpenHuggingFaceModal();
          navigate(buildPath('admin', `reservoir/${toLocalId(artifactId)}`));
        }}
        onCancel={toggleOpenHuggingFaceModal}
      />
      <BAIDeactivateArtifactsModal
        open={!!selectedArtifacts.length}
        selectedArtifactsFragment={selectedArtifacts}
        onCancel={() => setSelectedArtifacts([])}
        onOk={() => {
          updateFetchKey();
          setSelectedArtifacts([]);
          setSelectedArtifactIdList([]);
        }}
      />
      <BAIActivateArtifactsModal
        open={!!selectedRestoreArtifacts.length}
        selectedArtifactsFragment={selectedRestoreArtifacts}
        onCancel={() => setSelectedRestoreArtifacts([])}
        onOk={() => {
          updateFetchKey();
          setSelectedRestoreArtifacts([]);
          setSelectedArtifactIdList([]);
        }}
      />
      {/* TODO(needs-backend): HuggingFace registry setting modal is hidden
         until storage-proxy applies DB config via Redis stateful state sharing. */}
      {/* <BAIHuggingFaceRegistrySettingModal
        open={openHuggingFaceSettingModal}
        huggingFaceRegistryFrgmt={
          huggingfaceRegistries?.edges?.[0]?.node ?? null
        }
        onOk={() => toggleHuggingFaceSettingModal()}
        onCancel={() => toggleHuggingFaceSettingModal()}
      /> */}
    </BAIFlex>
  );
};

export default ReservoirPage;
